# 2. 계산 로직
# ============================================================

def concentration_score(name):
    p = PRODUCTS[name]
    score = (
        0.30 * p["social_heat"] +
        0.25 * p["price_heat"] +
        0.25 * p["trade_heat"] +
        0.20 * p["newbie_heat"]
    )
    return round(score, 1)

def concentration_level(score):
    if score < 40:
        return "LOW", "일반 주문", "low"
    elif score < 70:
        return "WATCH", "요약 신호 확인", "watch"
    elif score < 85:
        return "HIGH", "주문 전 경고 카드", "high"
    return "VERY HIGH", "상세 지표 재확인", "very-high"

def calc_order(name, amount):
    try:
        amount = int(float(amount))
    except:
        amount = 0

    price = PRODUCTS[name]["price"]

    if amount <= 0:
        return 0, 0, 0

    qty = amount // price
    used = qty * price
    remain = amount - used
    return qty, used, remain

def make_history(name):
    p = PRODUCTS[name]
    seed = sum(ord(c) for c in name)
    rng = np.random.default_rng(seed)

    n = 30
    vol = 0.011 if "2X" not in name else 0.022
    drift = (p["return5"] / 100) / 24

    returns = rng.normal(drift, vol, n)
    prices = p["base"] * np.cumprod(1 + returns)
    prices *= p["price"] / prices[-1]

    dates = pd.date_range(end=pd.Timestamp.today().normalize(), periods=n)

    return pd.DataFrame({"date": dates, "price": prices})

